def main():
    out = Path(__file__).parent / "codes.jsonl"
    seen = set()
    rows = []
    for id_, code, conf, reason in DECISIONS:
        assert id_ not in seen, id_
        seen.add(id_)
        assert code in {"execution", "recognition_or_interpretation", "mixed", "unreadable"}, code
        assert conf in {"low", "medium", "high"}, conf
        assert len(reason.split()) <= 20, (id_, reason)
        rows.append({"id": id_, "code": code, "one_line_reason": reason, "confidence": conf})
    rows.sort(key=lambda r: r["id"])
    with out.open("w") as f:
        for r in rows:
            f.write(json.dumps(r, ensure_ascii=False) + "\n")
    from collections import Counter
    c = Counter(r["code"] for r in rows)
    print("wrote", len(rows), "to", out)
    print("counts:", dict(c))


if __name__ == "__main__":
    main()
